import { createFile, MP4BoxBuffer } from "mp4box";

const SECONDS_PER_SEGMENT = 2;
const SECONDS_KEPT_BEHIND = 10;

export class VideoUnavailableError extends Error {}

export function canStreamVideo() {
  return typeof window !== "undefined" && typeof window.MediaSource === "function";
}

export function streamVideo(video, openStream, onFailure) {
  const mediaSource = new MediaSource();
  const url = URL.createObjectURL(mediaSource);
  const file = createFile();
  const tracks = [];
  let current = null;
  let generation = 0;
  let size = Infinity;
  let position = 0;
  let isBroken = false;
  let ready = false;
  let flushed = false;
  let closed = false;

  const stopStream = () => {
    if (current) current.stop();
    current = null;
  };

  const open = async (offset) => {
    stopStream();
    const started = ++generation;
    position = offset;
    isBroken = false;
    let handle;
    try {
      handle = await openStream(offset, (frame) => onFrame(started, frame));
    } catch (err) {
      if (started === generation) fail(err);
      return;
    }
    if (closed || started !== generation) {
      if (handle) handle.stop();
      return;
    }
    if (!handle) {
      fail(new VideoUnavailableError("video is not available"));
      return;
    }
    size = handle.size;
    current = handle;
  };

  const onFrame = (started, frame) => {
    if (closed || started !== generation) return;
    if (frame.error) {
      stopStream();
      isBroken = true;
      return;
    }
    if (frame.data.length > 0) {
      const end = frame.offset + frame.data.length;
      const next = file.appendBuffer(MP4BoxBuffer.fromArrayBuffer(toArrayBuffer(frame.data), frame.offset), end >= size);
      position = end;
      if (Number.isFinite(next) && next !== end && next < size) {
        open(next);
        return;
      }
    }
    if (frame.isLast) {
      stopStream();
      if (!flushed) {
        flushed = true;
        file.flush();
      }
    }
  };

  const append = (track) => {
    if (closed || mediaSource.readyState === "closed" || track.buffer.updating || track.queue.length === 0) return;
    const segment = track.queue.shift();
    track.appending = segment;
    try {
      track.buffer.appendBuffer(segment.buffer);
    } catch (err) {
      track.appending = null;
      if (err.name !== "QuotaExceededError") {
        fail(err);
        return;
      }
      track.queue.unshift(segment);
      const until = video.currentTime - SECONDS_KEPT_BEHIND;
      if (until > 0) track.buffer.remove(0, until);
    }
  };

  const onUpdateEnd = (track) => {
    const segment = track.appending;
    track.appending = null;
    if (segment && !segment.init) {
      file.releaseUsedSamples(track.id, segment.nextSample);
      track.done = segment.last;
    }
    const isFinished = tracks.every((t) => t.done && t.queue.length === 0 && !t.buffer.updating);
    if (isFinished && mediaSource.readyState === "open") {
      mediaSource.endOfStream();
      return;
    }
    append(track);
  };

  const resume = () => {
    tracks.forEach(append);
    if (isBroken && position < size) {
      open(position);
    }
  };

  const onSeeking = () => {
    if (!ready || closed) return;
    const { offset } = file.seek(video.currentTime, true);
    flushed = false;
    for (const track of tracks) {
      track.queue.length = 0;
      track.done = false;
    }
    open(offset);
  };

  file.onReady = (info) => {
    const audio = new Set(info.audioTracks);
    const playable = [...info.videoTracks, ...info.audioTracks];
    if (playable.length === 0) {
      fail(new Error("the file has no audio or video track"));
      return;
    }
    for (const t of playable) {
      const mime = `${audio.has(t) ? "audio" : "video"}/mp4; codecs="${t.codec}"`;
      if (!MediaSource.isTypeSupported(mime)) {
        fail(new Error(`this system cannot play ${mime}`));
        return;
      }
      const track = { id: t.id, buffer: mediaSource.addSourceBuffer(mime), queue: [], appending: null, done: false };
      track.buffer.addEventListener("updateend", () => onUpdateEnd(track));
      const seconds = Math.max(t.duration / t.timescale, 1);
      file.setSegmentOptions(t.id, track, { nbSamples: Math.max(1, Math.ceil((t.nb_samples / seconds) * SECONDS_PER_SEGMENT)) });
      tracks.push(track);
    }
    if (info.duration && info.timescale) {
      mediaSource.duration = info.duration / info.timescale;
    }
    for (const init of file.initializeSegmentation("per-track")) {
      init.user.queue.push({ buffer: init.buffer, init: true });
      append(init.user);
    }
    ready = true;
    file.start();
    file.seek(0, true);
  };

  file.onSegment = (id, track, buffer, nextSample, last) => {
    track.queue.push({ buffer, nextSample, last });
    append(track);
  };

  file.onError = (module, message) => fail(new Error(`${module}: ${message}`));

  const stop = () => {
    if (closed) return;
    closed = true;
    stopStream();
    video.removeEventListener("seeking", onSeeking);
    video.removeEventListener("timeupdate", resume);
    video.removeEventListener("waiting", resume);
    file.stop();
    URL.revokeObjectURL(url);
  };

  const fail = (err) => {
    if (closed) return;
    stop();
    onFailure(err);
  };

  video.addEventListener("seeking", onSeeking);
  video.addEventListener("timeupdate", resume);
  video.addEventListener("waiting", resume);
  mediaSource.addEventListener("sourceopen", () => open(0), { once: true });
  video.src = url;

  return { stop };
}

function toArrayBuffer(bytes) {
  if (bytes.byteOffset === 0 && bytes.byteLength === bytes.buffer.byteLength) {
    return bytes.buffer;
  }
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
}
